GO

BEGIN TRY
BEGIN TRANSACTION;

-- ---------------------------------------------------------------
-- Configuration
-- ---------------------------------------------------------------
DECLARE @by NVARCHAR(100) = N'anoop.ps@soffit.in';

DECLARE @release_id BIGINT, @type_id BIGINT;
DECLARE @ins_obl INT = 0, @ins_detail INT = 0, @ins_evid INT = 0;
DECLARE @ins_link INT = 0, @ins_map INT = 0, @ins_smap INT = 0;
DECLARE @sheet_rows INT = (SELECT COUNT(*) FROM #obl);
DECLARE @missing NVARCHAR(4000), @error NVARCHAR(4000);

-- ---------------------------------------------------------------
-- Preflight
-- ---------------------------------------------------------------
IF SCHEMA_ID('GRAC_New') IS NULL
    THROW 50540, 'Schema GRAC_New is missing. Run 001 first.', 1;
IF OBJECT_ID('GRAC_New.requirement_obligation','U') IS NULL
    THROW 50541, 'GRAC_New.requirement_obligation is missing. Run 001 and 019 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_type_master','U') IS NULL
    THROW 50542, 'GRAC_New.obligation_type_master is missing. Run 026 and 027 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_event_response','U') IS NULL
    THROW 50543, 'GRAC_New.obligation_event_response is missing. Run 026 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_event_response_evidence_link','U') IS NULL
    THROW 50544, 'GRAC_New.obligation_event_response_evidence_link is missing. Run 026 first.', 1;
IF OBJECT_ID('GRAC_New.obligation_requirement_release_map','U') IS NULL
    THROW 50545, 'GRAC_New.obligation_requirement_release_map is missing. Run 019 and 021 first.', 1;
IF COL_LENGTH('GRAC_New.obligation_requirement_release_map','framework_statement_id') IS NULL
    THROW 50546, 'obligation_requirement_release_map.framework_statement_id is missing. Run 021 first.', 1;
IF COL_LENGTH('GRAC_New.requirement_obligation','obligation_name') IS NULL
    THROW 50547, 'requirement_obligation.obligation_name is missing. Run 019 first.', 1;
IF COL_LENGTH('GRAC_New.requirement_obligation','keywords') IS NULL
    THROW 50548, 'requirement_obligation.keywords is missing. Run 023 first.', 1;
-- 055 is detected by the local variable it introduced into
-- cm_manage_repository's 'obligations' save branch:
--
--     DECLARE @obm_obligation_text NVARCHAR(MAX) = JSON_VALUE(@p_payload,'$.obligationText');
--
-- That name appears in 055 and every revision after it, and in none
-- before -- 050, the revision 055 replaced, writes obligation_text as a
-- copy of @obm_obligation_name and never declares it.  The JSON key
-- '$.obligationText' is NOT a usable marker: 050 already reads it in the
-- statement-obligation branch, so testing for that would pass on a
-- database where 055 was never applied.
--
-- The procedure also lives in dbo, not GRAC_New.
IF OBJECT_ID('dbo.cm_manage_repository') IS NULL
    THROW 50548, 'dbo.cm_manage_repository is missing. Run 002 and the later repository migrations first.', 1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m
              WHERE m.object_id = OBJECT_ID('dbo.cm_manage_repository')
                AND m.definition LIKE '%@obm_obligation_text%')
    THROW 50549, 'Migration 055 has not been applied -- dbo.cm_manage_repository does not declare @obm_obligation_text. Without 055 the procedure overwrites obligation_text with the Obligation Name on every save, and the Descriptions loaded here would not survive the first interactive Save. Run 055_obligation_description_field.sql first.', 1;

IF @sheet_rows <> 1194
BEGIN
    SET @error = CONCAT(N'Staging holds ', @sheet_rows, N' rows, expected 1194. The INSERT #obl block above is incomplete -- do not load a partial register.');
    THROW 50550, @error, 1;
END

-- ---------------------------------------------------------------
-- Validation
-- ---------------------------------------------------------------

-- 1. The obligation type must exist.
SELECT @type_id = obligation_type_id FROM GRAC_New.obligation_type_master WHERE type_code = N'EventResponse';
IF @type_id IS NULL
BEGIN
    SET @error = N'obligation_type_master has no row with type_code = ''EventResponse'' (type_name ''Event Response''). Run 027_obligation_taxonomy_migration.sql first.';
    THROW 50551, @error, 1;
END

-- 2. Every staged Practice Name must resolve to exactly one Practice.
IF EXISTS(SELECT 1 FROM #obl o
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r
                           WHERE r.requirement_name = o.practice_name))
BEGIN
    SET @missing = STUFF((SELECT DISTINCT TOP 20 N', ' + o.practice_name FROM #obl o
        WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement r WHERE r.requirement_name = o.practice_name)
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Practice(s) not found (first 20): ', @missing,
                        N'. Run 060_iso27001_v13_practices.sql first.');
    THROW 50552, @error, 1;
END

IF EXISTS(SELECT 1 FROM GRAC_New.requirement r
          WHERE EXISTS(SELECT 1 FROM #obl o WHERE o.practice_name = r.requirement_name)
          GROUP BY r.requirement_name HAVING COUNT(*) > 1)
BEGIN
    SET @error = N'A Practice Name this register references exists more than once in GRAC_New.requirement. Obligations would attach ambiguously. Resolve the duplicate before loading.';
    THROW 50553, @error, 1;
END

-- 3. Every Practice must carry an active Statement mapping from 060.
IF EXISTS(SELECT 1 FROM #obl o
          JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement_requirement_map m
                           WHERE m.requirement_id = r.requirement_id AND m.status = N'Active'))
BEGIN
    SET @missing = STUFF((SELECT DISTINCT TOP 20 N', ' + o.practice_name FROM #obl o
        JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
        WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.framework_statement_requirement_map m
                         WHERE m.requirement_id = r.requirement_id AND m.status = N'Active')
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Practice(s) with no active Statement mapping (first 20): ', @missing,
                        N'. Re-run 060.');
    THROW 50554, @error, 1;
END

-- Resolve every staged row to its Practice, Statement and Release.
SELECT o.seq,
       r.requirement_id,
       fs.framework_statement_id,
       fs.release_id,
       fs.statement_reference
INTO #res
FROM #obl o
JOIN GRAC_New.requirement r ON r.requirement_name = o.practice_name
JOIN GRAC_New.framework_statement_requirement_map m
     ON m.requirement_id = r.requirement_id AND m.status = N'Active'
JOIN GRAC_New.framework_statement fs
     ON fs.framework_statement_id = m.framework_statement_id;
CREATE UNIQUE CLUSTERED INDEX ux_res_seq ON #res(seq);

-- 4. Exactly one resolution per staged row.  A Practice mapped to two
--    Statements would otherwise fan its Obligations out silently.
IF (SELECT COUNT(*) FROM #res) <> @sheet_rows
BEGIN
    SET @error = CONCAT(N'Practice/Statement resolution produced ', (SELECT COUNT(*) FROM #res),
                        N' rows for ', @sheet_rows, N' sheet rows. A Practice is mapped to more than one Framework Statement.');
    THROW 50555, @error, 1;
END

IF (SELECT COUNT(DISTINCT release_id) FROM #res) > 1
BEGIN
    SET @error = N'The resolved Framework Statements belong to more than one Release. Load one release at a time.';
    THROW 50556, @error, 1;
END
SELECT TOP 1 @release_id = release_id FROM #res;

-- 5. (Practice, Obligation Name) must be unique inside this register.
IF EXISTS(SELECT 1 FROM #obl GROUP BY practice_name, obligation_name HAVING COUNT(*) > 1)
BEGIN
    SET @missing = STUFF((SELECT TOP 20 N', ' + x.practice_name + N' / ' + x.obligation_name FROM
        (SELECT practice_name, obligation_name FROM #obl
         GROUP BY practice_name, obligation_name HAVING COUNT(*) > 1) x
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Duplicate (Practice, Obligation Name) in the sheet (first 20): ', @missing,
                        N'. That pair is the natural key for this load.');
    THROW 50557, @error, 1;
END

-- 6. The control the Practices sheet put this row under must equal the
--    control 060's mapping actually resolved to.  See the header.
IF EXISTS(SELECT 1 FROM #obl o JOIN #res res ON res.seq = o.seq
          WHERE res.statement_reference <> o.statement_reference)
BEGIN
    SET @missing = STUFF((SELECT DISTINCT TOP 20 N', ' + o.practice_name
                                 + N': sheet says ' + o.statement_reference
                                 + N', mapping says ' + res.statement_reference
        FROM #obl o JOIN #res res ON res.seq = o.seq
        WHERE res.statement_reference <> o.statement_reference
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Control mismatch between the workbook and 060''s Practice mapping (first 20): ', @missing, N'.');
    THROW 50558, @error, 1;
END

-- 7. Every staged Evidence Type must resolve.
IF EXISTS(SELECT 1 FROM #obl o
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.evidence_type_master e
                           WHERE e.evidence_type_name = o.evidence_type AND e.is_active = 1))
BEGIN
    SET @missing = STUFF((SELECT DISTINCT N', ' + o.evidence_type FROM #obl o
        WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.evidence_type_master e
                         WHERE e.evidence_type_name = o.evidence_type AND e.is_active = 1)
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Evidence Type(s) not found in evidence_type_master: ', @missing,
                        N'. Run 059_iso27001_v13_masters.sql first.');
    THROW 50559, @error, 1;
END

-- 8. Prove the SLA text really is unparseable before discarding it.
--    If a future workbook supplies real numbers, this fires and the load
--    stops rather than silently dropping them into remarks.
IF EXISTS(SELECT 1 FROM #obl WHERE TRY_CONVERT(INT, LTRIM(RTRIM(sla_text))) IS NOT NULL)
BEGIN
    SET @missing = STUFF((SELECT TOP 20 N', ' + CAST(seq AS NVARCHAR(20)) + N': ' + sla_text
        FROM #obl WHERE TRY_CONVERT(INT, LTRIM(RTRIM(sla_text))) IS NOT NULL
        FOR XML PATH('')), 1, 2, N'');
    SET @error = CONCAT(N'Numeric SLA Value(s) found (first 20): ', @missing,
                        N'. This script deliberately leaves sla_value NULL because every row in v1.3 (4) is free text. Update the script to load them properly rather than losing them to remarks.');
    THROW 50564, @error, 1;
END

-- ---------------------------------------------------------------
-- Insert the Obligation parents
--
-- MERGE, not INSERT ... OUTPUT: OUTPUT alone cannot emit a source column,
-- so the only way to tie a new obligation_id back to its staging row would
-- be to re-find it by obligation_name -- which duplicated names break.
-- MERGE's OUTPUT can see the source, so seq travels with the id.
-- ON 1 = 0 makes every source row a NOT MATCHED insert; the source itself
-- is filtered to the rows that do not exist yet.
-- ---------------------------------------------------------------
CREATE TABLE #key(seq INT NOT NULL PRIMARY KEY, obligation_id BIGINT NOT NULL);

MERGE GRAC_New.requirement_obligation AS tgt
USING (
    SELECT o.seq, res.requirement_id, o.obligation_name, o.obligation_desc, o.keywords,
           o.practice_ref, o.statement_reference
    FROM #obl o
    JOIN #res res ON res.seq = o.seq
    WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement_obligation x
                     WHERE x.requirement_id  = res.requirement_id
                       AND x.obligation_name = o.obligation_name)
) AS src
ON 1 = 0
WHEN NOT MATCHED THEN
    INSERT (requirement_id, release_id, obligation_type_id, obligation_name,
            obligation_text, keywords, remarks, status, entered_by)
    VALUES (src.requirement_id, @release_id, @type_id, src.obligation_name,
            src.obligation_desc, src.keywords,
            CONCAT(N'Bulk load 064. Import Practice & Obligation Mapping v1.3 (4).xlsx, sheet Event Response Register, Sl No ', src.seq,
                   N'. Practice ID: ', src.practice_ref,
                   N'. Source control: ', src.statement_reference, N'.'),
            N'Active', @by)
OUTPUT inserted.obligation_id, src.seq INTO #key(obligation_id, seq);

SET @ins_obl = @@ROWCOUNT;

-- Top up #key with rows that already existed, so a re-run after a partial
-- failure repairs their detail, evidence and mapping instead of skipping
-- the Obligation whole.
INSERT #key(seq, obligation_id)
SELECT o.seq, MIN(ro.obligation_id)
FROM #obl o
JOIN #res res ON res.seq = o.seq
JOIN GRAC_New.requirement_obligation ro
     ON ro.requirement_id  = res.requirement_id
    AND ro.obligation_name = o.obligation_name
WHERE NOT EXISTS(SELECT 1 FROM #key k WHERE k.seq = o.seq)
GROUP BY o.seq;

IF (SELECT COUNT(*) FROM #key) <> @sheet_rows
BEGIN
    SET @error = CONCAT(N'#key holds ', (SELECT COUNT(*) FROM #key), N' rows for ', @sheet_rows,
                        N' staged rows. An Obligation failed to resolve to an id -- nothing further was written.');
    THROW 50560, @error, 1;
END

-- ---------------------------------------------------------------
-- Event Response detail
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_event_response
    (obligation_id, trigger_event, response_action, sla_value, sla_unit,
     escalation_path, remarks, status, entered_by)
SELECT k.obligation_id, o.trigger_event, o.response_action,
       NULL, NULL,
       o.escalation_path,
       CONCAT(N'Bulk load 064. Sheet Sl No ', o.seq,
              N'. Sheet SLA (free text, not numeric -- retained here): ',
              ISNULL(o.sla_text, N'(blank)'),
              N' / ', ISNULL(o.sla_unit_text, N'(blank)'), N'.'),
       N'Active', @by
FROM #obl o
JOIN #key k ON k.seq = o.seq
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_event_response x
                 WHERE x.obligation_id = k.obligation_id AND x.status = N'Active');
SET @ins_detail = @@ROWCOUNT;

-- ---------------------------------------------------------------
-- Evidence spec + type-specific link
-- ---------------------------------------------------------------
INSERT GRAC_New.requirement_obligation_evidence
    (obligation_id, evidence_type_id, frequency_id, retention_requirement, remarks, status, entered_by)
SELECT k.obligation_id, e.evidence_type_id, NULL, NULL, o.evidence_desc, N'Active', @by
FROM #obl o
JOIN #key k ON k.seq = o.seq
JOIN GRAC_New.evidence_type_master e
     ON e.evidence_type_name = o.evidence_type AND e.is_active = 1
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement_obligation_evidence x
                 WHERE x.obligation_id    = k.obligation_id
                   AND x.evidence_type_id = e.evidence_type_id
                   AND x.status           = N'Active');
SET @ins_evid = @@ROWCOUNT;

INSERT GRAC_New.obligation_event_response_evidence_link(obligation_id, obligation_evidence_id, status, entered_by)
SELECT k.obligation_id, ev.obligation_evidence_id, N'Active', @by
FROM #key k
JOIN GRAC_New.requirement_obligation_evidence ev
     ON ev.obligation_id = k.obligation_id AND ev.status = N'Active'
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_event_response_evidence_link x
                 WHERE x.obligation_id          = k.obligation_id
                   AND x.obligation_evidence_id = ev.obligation_evidence_id
                   AND x.status                 = N'Active');
SET @ins_link = @@ROWCOUNT;

-- ---------------------------------------------------------------
-- Obligation -> Practice + Release + Statement mapping
--
-- This is the authoritative link (019 decoupled the parent, 021 added the
-- Statement column).
-- ---------------------------------------------------------------
INSERT GRAC_New.obligation_requirement_release_map
    (obligation_id, requirement_id, release_id, framework_statement_id, status, entered_by)
SELECT k.obligation_id, res.requirement_id, @release_id, res.framework_statement_id, N'Active', @by
FROM #key k
JOIN #res res ON res.seq = k.seq
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_requirement_release_map m
                 WHERE m.obligation_id          = k.obligation_id
                   AND m.requirement_id         = res.requirement_id
                   AND m.release_id             = @release_id
                   AND m.framework_statement_id = res.framework_statement_id);
SET @ins_map = @@ROWCOUNT;

-- 056's direct Obligation -> Statement index, used by the eligibility read.
IF OBJECT_ID('GRAC_New.obligation_framework_statement_map','U') IS NOT NULL
BEGIN
    INSERT GRAC_New.obligation_framework_statement_map
        (obligation_id, framework_statement_id, status, entered_by)
    SELECT k.obligation_id, res.framework_statement_id, N'Active', @by
    FROM #key k
    JOIN #res res ON res.seq = k.seq
    WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_framework_statement_map m
                     WHERE m.obligation_id          = k.obligation_id
                       AND m.framework_statement_id = res.framework_statement_id);
    SET @ins_smap = @@ROWCOUNT;
END

-- ---------------------------------------------------------------
-- Final assertion: every staged row now has detail, evidence and mapping.
-- ---------------------------------------------------------------
IF EXISTS(SELECT 1 FROM #key k
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_event_response d
                           WHERE d.obligation_id = k.obligation_id AND d.status = N'Active'))
BEGIN
    SET @error = N'One or more Obligations have no active Event Response detail row after load.';
    THROW 50561, @error, 1;
END

IF EXISTS(SELECT 1 FROM #key k
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.requirement_obligation_evidence d
                           WHERE d.obligation_id = k.obligation_id AND d.status = N'Active'))
BEGIN
    SET @error = N'One or more Obligations have no active evidence row after load.';
    THROW 50562, @error, 1;
END

IF EXISTS(SELECT 1 FROM #key k
          WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_requirement_release_map m
                           WHERE m.obligation_id = k.obligation_id AND m.status = N'Active'))
BEGIN
    SET @error = N'One or more Obligations have no active Practice/Release/Statement mapping after load.';
    THROW 50563, @error, 1;
END

-- ---------------------------------------------------------------
-- Audit trail
--
-- Mirrors the three-table shape cm_manage_repository writes, so these rows
-- render on the Audit Trace screen like any other Add.  Only newly
-- inserted Obligations get an event; a re-run that only repaired detail
-- rows does not re-announce the Obligation.
-- ---------------------------------------------------------------
DECLARE @events TABLE(audit_event_id BIGINT, entity_id BIGINT);

INSERT GRAC_New.audit_trace_event
    (entity_type,entity_id,action_type,table_name,record_reference,remarks,before_json,after_json,status,entered_by)
OUTPUT inserted.audit_event_id, inserted.entity_id INTO @events
SELECT N'obligations', ro.obligation_id, N'Add',
       N'GRAC_New.requirement_obligation',
       CONCAT(r.requirement_code, N' - ', ro.obligation_name),
       ro.remarks,
       NULL,
       (SELECT ro.obligation_name name, ro.obligation_text [text], ro.keywords,
               N'Event Response' obligationType, r.requirement_code practiceCode,
               r.requirement_name practiceName, ro.status
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       N'Active', @by
FROM #key k
JOIN GRAC_New.requirement_obligation ro ON ro.obligation_id = k.obligation_id
JOIN #res res ON res.seq = k.seq
JOIN GRAC_New.requirement r ON r.requirement_id = res.requirement_id
WHERE NOT EXISTS(SELECT 1 FROM GRAC_New.audit_trace_event ae
                 WHERE ae.entity_type = N'obligations'
                   AND ae.entity_id   = k.obligation_id
                   AND ae.action_type = N'Add');

INSERT GRAC_New.audit_trace_detail(audit_event_id,field_name,old_value,new_value,entered_by)
SELECT e.audit_event_id, d.field_name, NULL, d.new_value, @by
FROM @events e
JOIN GRAC_New.requirement_obligation ro ON ro.obligation_id = e.entity_id
CROSS APPLY (VALUES
    (N'Obligation Name',        ro.obligation_name),
    (N'Obligation Description', CAST(ro.obligation_text AS NVARCHAR(MAX))),
    (N'Obligation Type',        N'Event Response'),
    (N'Keywords',               CAST(ro.keywords AS NVARCHAR(MAX))),
    (N'Status',                 ro.status)
) AS d(field_name, new_value)
WHERE d.new_value IS NOT NULL;

INSERT GRAC_New.audit_trace
    (audit_event_id,entity_type,entity_id,action_type,table_name,record_reference,remarks,after_json,status,entered_by)
SELECT ev.audit_event_id, ev.entity_type, ev.entity_id, ev.action_type, ev.table_name,
       ev.record_reference, ev.remarks, ev.after_json, N'Active', @by
FROM GRAC_New.audit_trace_event ev
JOIN @events e ON e.audit_event_id = ev.audit_event_id;

COMMIT TRANSACTION;

PRINT CONCAT(N'064 complete. Release ', @release_id, N' | Event Response Obligations inserted ', @ins_obl,
             N' | skipped ', @sheet_rows - @ins_obl, N' already present',
             N' | detail ', @ins_detail, N' | evidence ', @ins_evid, N' | evidence links ', @ins_link,
             N' | practice mappings ', @ins_map, N' | statement mappings ', @ins_smap, N'.');
PRINT N'Next: run 065_iso27001_v13_constraint.sql.';

END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH
GO

-- ---------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------
-- Expect 1194 Event Response Obligations, each with one detail row, one evidence
-- row, one evidence link and one Practice/Release/Statement mapping.
SELECT N'Event Response obligations' AS Metric, COUNT(*) AS Actual, 1194 AS Expected
FROM GRAC_New.requirement_obligation ro
JOIN GRAC_New.obligation_type_master t ON t.obligation_type_id = ro.obligation_type_id
WHERE t.type_code = N'EventResponse' AND ro.status = N'Active'
UNION ALL
SELECT N'obligation_event_response', COUNT(*), 1194
FROM GRAC_New.obligation_event_response WHERE status = N'Active'
UNION ALL
SELECT N'obligation_event_response_evidence_link', COUNT(*), 1194
FROM GRAC_New.obligation_event_response_evidence_link WHERE status = N'Active';
GO

-- Any Event Response Obligation missing a detail row. Expect 0 rows.
SELECT ro.obligation_id, ro.obligation_name
FROM GRAC_New.requirement_obligation ro
JOIN GRAC_New.obligation_type_master t ON t.obligation_type_id = ro.obligation_type_id
WHERE t.type_code = N'EventResponse' AND ro.status = N'Active'
  AND NOT EXISTS(SELECT 1 FROM GRAC_New.obligation_event_response d
                 WHERE d.obligation_id = ro.obligation_id AND d.status = N'Active');
GO

-- Spot-check the way the Obligation Master screen shows it.
SELECT TOP 20 r.requirement_code, r.requirement_name AS practice,
       ro.obligation_name, fs.statement_reference, e.evidence_type_name
FROM GRAC_New.requirement_obligation ro
JOIN GRAC_New.obligation_type_master t ON t.obligation_type_id = ro.obligation_type_id
JOIN GRAC_New.obligation_requirement_release_map m ON m.obligation_id = ro.obligation_id AND m.status = N'Active'
JOIN GRAC_New.requirement r          ON r.requirement_id          = m.requirement_id
JOIN GRAC_New.framework_statement fs ON fs.framework_statement_id = m.framework_statement_id
LEFT JOIN GRAC_New.requirement_obligation_evidence ev ON ev.obligation_id = ro.obligation_id AND ev.status = N'Active'
LEFT JOIN GRAC_New.evidence_type_master e ON e.evidence_type_id = ev.evidence_type_id
WHERE t.type_code = N'EventResponse' AND ro.status = N'Active'
ORDER BY r.requirement_code, ro.obligation_name;
GO
